write_result() {          # $1=NAME $2=VALUE
  if [ "$#" -ne 2 ] || [[ ! "$1" =~ ^[A-Z_][A-Z0-9_]*$ ]] || [[ "$1" == __Y2B_* ]]; then
    echo "write_result: expected 'write_result NAME VALUE' with NAME matching ^[A-Z_][A-Z0-9_]*\$ (step $Y2B_STEP_NAME)" >> "$LOG_FILE"
    return 1
  fi
  printf '%s=%s\n' "$1" "$(printf '%s' "$2" | base64 -w0)" >> "$RES_FILE"
  printf '%s="%s"\n' "$1" "$2" >> "$LOG_FILE"
}
export -f write_result; export RES_FILE LOG_FILE

y2b_step_1() {            # say-hello
  HOSTNAME_VAL=$(hostname 2>/dev/null || uname -n 2>/dev/null || echo "unknown")
  write_result HELLO "Hello from ${HOSTNAME_VAL} via y2b"
  write_result SHELL_VERSION "$BASH_VERSION"
}
y2b_step_2() {            # do-math
  sum=0
  for ((i=1; i<=100; i++)); do
    sum=$((sum + i))
  done
  fact=1
  for ((i=1; i<=10; i++)); do
    fact=$((fact * i))
  done
  cpus=$(nproc 2>/dev/null || grep -c ^processor /proc/cpuinfo 2>/dev/null || echo 1)
  if [ -z "$cpus" ] || [ "$cpus" -lt 1 ] 2>/dev/null; then
    cpus=1
  fi
  cpu_x1024=$((cpus * 1024))
  write_result MATH_SUM "$sum"
  write_result MATH_FACT10 "$fact"
  write_result MATH_CPU_X1024 "$cpu_x1024"
}
y2b_step_3() {            # get-system-info
  if [ -f /etc/os-release ]; then
    . /etc/os-release
    write_result OS_NAME "$NAME"
    write_result OS_VERSION "$VERSION_ID"
  else
    write_result OS_NAME "UNKNOWN"
    write_result OS_VERSION "UNKNOWN"
  fi

  KERNEL_VAL=$(uname -r 2>/dev/null || echo "N/A")
  write_result KERNEL "$KERNEL_VAL"

  CPU_VAL=$(nproc 2>/dev/null || grep -c ^processor /proc/cpuinfo 2>/dev/null || echo "N/A")
  write_result CPU_COUNT "$CPU_VAL"

  MEM_VAL=$(awk '/MemTotal/ {print int($2/1024)}' /proc/meminfo 2>/dev/null || echo "N/A")
  [ -n "$MEM_VAL" ] || MEM_VAL="N/A"
  write_result MEM_MB "$MEM_VAL"

  UPTIME_VAL=$(awk '{print int($1)}' /proc/uptime 2>/dev/null || echo "N/A")
  [ -n "$UPTIME_VAL" ] || UPTIME_VAL="N/A"
  write_result UPTIME_SECS "$UPTIME_VAL"

  VM_SIZE_VAL="N/A"
  LOCATION_VAL="N/A"
  if command -v curl >/dev/null 2>&1; then
    vms=$(curl -s -f -m 3 -H "Metadata: true" "http://169.254.169.254/metadata/instance/compute/vmSize?api-version=2021-02-01&format=text" 2>/dev/null)
    [ -n "$vms" ] && VM_SIZE_VAL="$vms"
    loc=$(curl -s -f -m 3 -H "Metadata: true" "http://169.254.169.254/metadata/instance/compute/location?api-version=2021-02-01&format=text" 2>/dev/null)
    [ -n "$loc" ] && LOCATION_VAL="$loc"
  fi
  write_result VM_SIZE "$VM_SIZE_VAL"
  write_result LOCATION "$LOCATION_VAL"
}
y2b_step_4() {            # get-updates
  UPD_COUNT_VAL="0"
  UPD_LATEST_VAL="NONE"
  UPD_LATEST_DATE_VAL="NONE"
  KERNEL_COUNT_VAL="0"

  if command -v rpm >/dev/null 2>&1; then
    cnt=$(rpm -qa 2>/dev/null | wc -l | tr -d ' ')
    [ -n "$cnt" ] && UPD_COUNT_VAL="$cnt"
    line=$(rpm -qa --last 2>/dev/null | head -n 1)
    if [ -n "$line" ]; then
      UPD_LATEST_VAL=$(echo "$line" | awk '{print $1}')
      UPD_LATEST_DATE_VAL=$(echo "$line" | awk '{$1=""; sub(/^[ \t]+/, ""); print}')
    fi
    kcnt=$(rpm -q kernel kernel-uek 2>/dev/null | grep -v 'is not installed' | wc -l | tr -d ' ')
    [ -n "$kcnt" ] && KERNEL_COUNT_VAL="$kcnt"
  fi

  write_result UPD_COUNT "$UPD_COUNT_VAL"
  write_result UPD_LATEST "$UPD_LATEST_VAL"
  write_result UPD_LATEST_DATE "$UPD_LATEST_DATE_VAL"
  write_result KERNEL_COUNT "$KERNEL_COUNT_VAL"
}
y2b_step_5() {            # download-package
  DEMO_DIR="/var/tmp/y2demo/pkg"
  mkdir -p "$DEMO_DIR"
  rm -rf "${DEMO_DIR:?}"/*

  URL="https://files.pythonhosted.org/packages/d9/5a/e7c31adbe875f2abbb91bd84cf2dc52d792b5a01506781dbcf25c91daf11/six-1.16.0-py2.py3-none-any.whl"
  EXPECTED_HASH="8abb2f1d86890a2dfb989f9a77cfcfd3e47c2a354b01111771326f8aa26e0254"
  TARGET="$DEMO_DIR/six-1.16.0-py2.py3-none-any.whl"

  DL_STATUS="NO_EGRESS"
  DL_BYTES="0"
  DL_SHA256_12="NONE"

  if command -v curl >/dev/null 2>&1; then
    if curl -fsSL --max-time 20 "$URL" -o "$TARGET" 2>/dev/null; then
      if [ -s "$TARGET" ]; then
        b=$(wc -c < "$TARGET" 2>/dev/null | tr -d ' ')
        [ -n "$b" ] && DL_BYTES="$b"
        if command -v sha256sum >/dev/null 2>&1; then
          calc_hash=$(sha256sum "$TARGET" 2>/dev/null | awk '{print $1}')
          DL_SHA256_12=$(echo "$calc_hash" | cut -c 1-12)
          if [ "$calc_hash" = "$EXPECTED_HASH" ]; then
            DL_STATUS="OK"
          else
            DL_STATUS="HASH_MISMATCH"
          fi
        fi
      else
        rm -f "$TARGET"
        DL_STATUS="NO_EGRESS"
      fi
    else
      rm -f "$TARGET"
      DL_STATUS="NO_EGRESS"
    fi
  fi

  write_result DL_STATUS "$DL_STATUS"
  write_result DL_BYTES "$DL_BYTES"
  write_result DL_SHA256_12 "$DL_SHA256_12"
}
y2b_step_6() {            # dedupe-packages
  DEMO_DIR="/var/tmp/y2demo/pkg"
  mkdir -p "$DEMO_DIR"

  ORIG_FILE=$(find "$DEMO_DIR" -maxdepth 1 -type f -name "*.whl" 2>/dev/null | head -n 1)
  if [ -n "$ORIG_FILE" ] && [ -s "$ORIG_FILE" ]; then
    DEDUP_SOURCE="download"
    cp "$ORIG_FILE" "$DEMO_DIR/duplicate_1.bin"
    cp "$ORIG_FILE" "$DEMO_DIR/duplicate_2.bin"
    echo "different unique content 12345" > "$DEMO_DIR/unique_file.txt"
  else
    DEDUP_SOURCE="local"
    rm -rf "${DEMO_DIR:?}"/*
    echo "local base package content" > "$DEMO_DIR/sample_base.pkg"
    cp "$DEMO_DIR/sample_base.pkg" "$DEMO_DIR/sample_dup1.pkg"
    cp "$DEMO_DIR/sample_base.pkg" "$DEMO_DIR/sample_dup2.pkg"
    echo "different unique content 12345" > "$DEMO_DIR/sample_unique.pkg"
  fi

  DUP_FOUND=0
  DUP_DELETED=0
  PREV_HASH=""

  sha256sum "$DEMO_DIR"/* 2>/dev/null | sort -k1,1 -k2,2 > "$DEMO_DIR/.hashes"
  while read -r hash filepath; do
    [ -z "$hash" ] && continue
    if [ "$hash" = "$PREV_HASH" ]; then
      DUP_FOUND=$((DUP_FOUND + 1))
      if rm -f "$filepath"; then
        DUP_DELETED=$((DUP_DELETED + 1))
      fi
    else
      PREV_HASH="$hash"
    fi
  done < "$DEMO_DIR/.hashes"
  rm -f "$DEMO_DIR/.hashes"

  FILES_LEFT=$(find "$DEMO_DIR" -maxdepth 1 -type f 2>/dev/null | wc -l | tr -d ' ')

  write_result DUP_FOUND "$DUP_FOUND"
  write_result DUP_DELETED "$DUP_DELETED"
  write_result FILES_LEFT "$FILES_LEFT"
  write_result DEDUP_SOURCE "$DEDUP_SOURCE"
}
y2b_step_7() {            # cleanup
  rm -rf /var/tmp/y2demo
  if [ ! -e /var/tmp/y2demo ]; then
    write_result CLEANUP "OK"
  else
    write_result CLEANUP "FAILED"
  fi
}
